#!/bin/zsh
# Local development build of MixBar.app (this Mac's architecture only).
# No Xcode required — Command Line Tools are enough. To ship a release to
# everyone's in-app updater, use ./release.sh instead.
set -e
cd "$(dirname "$0")"
VERSION=$(cat VERSION)
BUILT=$(date "+%b %d, %H:%M")
FEED="${UPDATE_FEED-https://raw.githubusercontent.com/jonpikereally/TotalMixMenuBar/main/updates/latest.json}"
cat > Sources/MixBar/Version.swift <<SWIFT
// Generated by build.sh / release.sh — do not edit.
enum AppVersion {
    static let version = "$VERSION"
    static let built = "$BUILT"
    static let updateFeed = "$FEED"
}
SWIFT
CACHE="${TMPDIR:-/tmp}/mixbar-modcache"
mkdir -p "$CACHE" MixBar.app/Contents/MacOS
cp Resources/Info.plist MixBar.app/Contents/Info.plist
/usr/libexec/PlistBuddy -c "Set :CFBundleShortVersionString $VERSION" MixBar.app/Contents/Info.plist
swiftc -O -target arm64-apple-macos13 -module-cache-path "$CACHE" -o MixBar.app/Contents/MacOS/MixBar Sources/MixBar/*.swift
codesign --force --sign - MixBar.app
echo "Built MixBar.app v$VERSION ($BUILT)"
